package com.cushty;

import com.cushty.api.BingoModels;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Pattern;

/**
 * ASCII-safe bingo board text for the RuneLite sidebar (RS font has no fancy glyphs).
 */
final class BingoFormat
{
	private static final Pattern GENERIC_TILE_NAME = Pattern.compile("(?i)^tile\\s*\\d*$");
	private static final int HISTORY_LIMIT = 8;
	private static final DateTimeFormatter HISTORY_TIME =
		DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.systemDefault());

	private BingoFormat()
	{
	}

	static String formatBoard(BingoModels.Board board, BingoModels.History history)
	{
		List<BingoModels.Tile> tiles = new ArrayList<>(board.getTiles());
		tiles.sort(Comparator.comparingInt(BingoModels.Tile::getY).thenComparingInt(BingoModels.Tile::getX));
		long done = tiles.stream().filter(BingoModels.Tile::isComplete).count();

		StringBuilder sb = new StringBuilder();
		sb.append(board.getEventName()).append('\n');
		sb.append(board.getTeamName())
			.append(" - ")
			.append(board.getWidth())
			.append('x')
			.append(board.getHeight())
			.append('\n');
		sb.append(done).append('/').append(tiles.size()).append(" tiles done\n\n");

		int n = 1;
		for (BingoModels.Tile tile : tiles)
		{
			sb.append(tile.isComplete() ? "[x] " : "[ ] ")
				.append(tileLine(tile, n++))
				.append('\n');
		}

		sb.append("\nRecent\n");
		sb.append(formatHistory(history, tiles));
		return sb.toString().trim();
	}

	/** One tile: "#1 Molch pearl" / "#2 Clue scroll" — never "Tile 1 - Tile 1". */
	static String tileLine(BingoModels.Tile tile, int n)
	{
		String label = tileLabel(tile, n);
		return "#" + n + " " + label;
	}

	static String tileLabel(BingoModels.Tile tile, int n)
	{
		String name = tile.getName() != null ? tile.getName().trim() : "";
		if (!isGenericName(name, n))
		{
			return name;
		}
		String fromReqs = summarizeRequirements(tile);
		if (fromReqs != null)
		{
			return fromReqs;
		}
		return "manual";
	}

	static boolean isGenericName(String name, int n)
	{
		if (name == null || name.isEmpty())
		{
			return true;
		}
		if (GENERIC_TILE_NAME.matcher(name.trim()).matches())
		{
			return true;
		}
		return name.trim().equalsIgnoreCase("Tile " + n);
	}

	/**
	 * Compact requirement summary, e.g. {@code Molch pearl}, {@code 0/5 Water Rune},
	 * {@code A + B}, {@code A or B}, {@code any 3 of: A, B, C}.
	 */
	static String summarizeRequirements(BingoModels.Tile tile)
	{
		List<BingoModels.TileGroup> groups = tile.getGroups();
		if (groups == null || groups.isEmpty())
		{
			return null;
		}
		List<String> groupParts = new ArrayList<>();
		for (BingoModels.TileGroup group : groups)
		{
			if (group == null || group.getItems() == null || group.getItems().isEmpty())
			{
				continue;
			}
			if ("pool".equalsIgnoreCase(group.getMode()))
			{
				int need = group.getPoolQty() != null ? group.getPoolQty() : group.getItems().size();
				List<String> names = new ArrayList<>();
				for (BingoModels.TileItem item : group.getItems())
				{
					names.add(item.getItemName() != null ? item.getItemName() : ("item " + item.getItemId()));
				}
				groupParts.add("any " + need + " of: " + String.join(", ", names));
				continue;
			}
			List<String> andParts = new ArrayList<>();
			for (BingoModels.TileItem item : group.getItems())
			{
				andParts.add(formatItem(item, tile.isComplete()));
			}
			groupParts.add(String.join(" + ", andParts));
		}
		if (groupParts.isEmpty())
		{
			return null;
		}
		return String.join(" or ", groupParts);
	}

	static String formatItem(BingoModels.TileItem item, boolean tileComplete)
	{
		String name = item.getItemName() != null && !item.getItemName().isEmpty()
			? item.getItemName()
			: ("item " + item.getItemId());
		if (item.getRequiredQty() <= 1)
		{
			return name;
		}
		if (tileComplete)
		{
			return item.getRequiredQty() + "x " + name;
		}
		int progress = Math.max(0, item.getProgress());
		return progress + "/" + item.getRequiredQty() + " " + name;
	}

	static String formatHistory(BingoModels.History history, List<BingoModels.Tile> tiles)
	{
		if (history == null || history.getEntries() == null || history.getEntries().isEmpty())
		{
			return "No activity yet.";
		}
		StringBuilder sb = new StringBuilder();
		int shown = 0;
		for (BingoModels.HistoryEntry entry : history.getEntries())
		{
			if (shown >= HISTORY_LIMIT)
			{
				break;
			}
			if ("REVERSED".equalsIgnoreCase(entry.getStatus()))
			{
				continue;
			}
			int tileNum = tileNumber(tiles, entry.getX(), entry.getY());
			String when = historyTime(entry.getCreatedAt());
			String tileRef = "#" + tileNum;
			String line;
			if (entry.getItemId() == 0)
			{
				line = when + " - " + tileRef + " marked done";
			}
			else
			{
				String item = entry.getItemName() != null ? entry.getItemName() : ("item " + entry.getItemId());
				line = when + " - +" + entry.getQuantity() + " " + item + " (" + tileRef + ")";
			}
			sb.append("- ").append(line).append('\n');
			shown++;
		}
		if (shown == 0)
		{
			return "No activity yet.";
		}
		return sb.toString().trim();
	}

	static int tileNumber(List<BingoModels.Tile> tiles, int x, int y)
	{
		int n = 1;
		for (BingoModels.Tile tile : tiles)
		{
			if (tile.getX() == x && tile.getY() == y)
			{
				return n;
			}
			n++;
		}
		return Math.max(1, y * 10 + x + 1);
	}

	private static String historyTime(long createdAtMs)
	{
		return HISTORY_TIME.format(Instant.ofEpochMilli(createdAtMs));
	}
}

package com.cushty;

import com.cushty.capture.CaptureArea;
import com.cushty.loot.LootFilter;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CushtyConfig.GROUP)
public interface CushtyConfig extends Config
{
	String GROUP = "cushty";
	String THIRD_PARTY_WARNING = "This plugin submits your IP address to a 3rd party website not controlled or verified by the RuneLite Developers.";

	@ConfigSection(
		name = "Connection",
		description = "Where to send events. There is no default server. Paste a server URL and a bearer token. Nothing is uploaded until you enable a feature below.",
		position = 0
	)
	String connectionSection = "connection";

	@ConfigSection(
		name = "Capture",
		description = "What is included in every screenshot: drops, pets, and manual shots",
		position = 1
	)
	String captureSection = "capture";

	@ConfigSection(
		name = "Screenshots",
		description = "Manual screenshots",
		position = 2
	)
	String screenshotSection = "screenshots";

	@ConfigSection(
		name = "Valuable drops",
		description = "Automatically share valuable drops",
		position = 3
	)
	String lootSection = "loot";

	@ConfigSection(
		name = "Pets",
		description = "Automatically share pet drops",
		position = 4
	)
	String petSection = "pets";

	@ConfigSection(
		name = "Bingo",
		description = "Clan bingo: watch server-configured tile items (including low-value) and show your team board",
		position = 5
	)
	String bingoSection = "bingo";

	@ConfigItem(
		keyName = "serverUrl",
		name = "Server URL",
		description = "HTTPS server that receives your events. There is no default. Leave blank to send nothing. Test connection also contacts this server.",
		section = connectionSection,
		position = 0
	)
	default String serverUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "token",
		name = "Token",
		description = "Bearer token for the server above. Treat it like a password.",
		secret = true,
		section = connectionSection,
		position = 1
	)
	default String token()
	{
		return "";
	}

	@ConfigItem(
		keyName = "includeRsn",
		name = "Include RSN",
		description = "Show your in-game name on posts. When off, your Discord name is used.",
		section = connectionSection,
		position = 2
	)
	default boolean includeRsn()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatNotifications",
		name = "Chat notifications",
		description = "Print a game chat message when something is sent or fails",
		section = connectionSection,
		position = 3
	)
	default boolean chatNotifications()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hidePrivateChat",
		name = "Hide private chat",
		description = "Leave private messages out of every screenshot. Chat is redrawn without them for the captured frame, then restored. The split private-chat window is hidden for that frame too.",
		section = captureSection,
		position = 0
	)
	default boolean hidePrivateChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "captureArea",
		name = "Capture area",
		description = "Entire screen is the game view. Chatbox is only the chatbox. A manual snip uses the area you drag instead.",
		section = captureSection,
		position = 1
	)
	default CaptureArea captureArea()
	{
		return CaptureArea.ENTIRE_SCREEN;
	}

	@ConfigItem(
		keyName = "manualEnabled",
		name = "Enable manual screenshots",
		description = "Send a screenshot with the hotkey or the sidebar. Snip drags a region of the game view. The other button uses Capture area.",
		warning = THIRD_PARTY_WARNING,
		section = screenshotSection,
		position = 0
	)
	default boolean manualEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "screenshotHotkey",
		name = "Screenshot hotkey",
		description = "Hotkey that sends a screenshot of the capture area immediately",
		section = screenshotSection,
		position = 1
	)
	default Keybind screenshotHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "lootEnabled",
		name = "Enable valuable drops",
		description = "Send a screenshot when you receive a valuable drop",
		warning = THIRD_PARTY_WARNING,
		section = lootSection,
		position = 0
	)
	default boolean lootEnabled()
	{
		return false;
	}

	@Range(min = LootFilter.MIN_STACK_VALUE)
	@Units(" gp")
	@ConfigItem(
		keyName = "lootMinValue",
		name = "Minimum value",
		description = "Send when a single item stack in a drop is worth at least this much (Grand Exchange price). Cannot be set below 5M.",
		section = lootSection,
		position = 1
	)
	default int lootMinValue()
	{
		return LootFilter.MIN_STACK_VALUE;
	}

	@ConfigItem(
		keyName = "petsEnabled",
		name = "Enable pets",
		description = "Send a screenshot when you get a pet (including duplicates)",
		warning = THIRD_PARTY_WARNING,
		section = petSection,
		position = 0
	)
	default boolean petsEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "bingoEnabled",
		name = "Enable bingo",
		description = "Fetch your team's bingo watchlist and board from the server. Matching loot (any value) is submitted like a drop. You must already be assigned to a team in Discord.",
		warning = THIRD_PARTY_WARNING,
		section = bingoSection,
		position = 0
	)
	default boolean bingoEnabled()
	{
		return false;
	}
}

package com.cushty;

import com.cushty.api.BingoModels;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar: Connection, Manual screenshots, and Bingo — kept simple for players in-game.
 * RuneLite's font only has basic glyphs, so bingo text stays ASCII.
 */
class CushtyPanel extends PluginPanel
{
	private static final int MAX_CAPTION = 500;

	private final JTextArea caption = new JTextArea(3, 20);
	private final JButton sendButton = new JButton("Full screen");
	private final JButton snipButton = new JButton("Snip");
	private final JButton testButton = new JButton("Test connection");
	private final JButton refreshBingoButton = new JButton("Refresh board");
	private final JTextArea bingoBoard = new JTextArea(10, 20);
	/** Shown under Test connection (and reused for snip/send feedback). */
	private final JLabel status = new JLabel(" ");
	private boolean busy;
	private boolean snipping;

	CushtyPanel(Consumer<String> onSend, Runnable onSnip, Runnable onTest, Runnable onRefreshBingo)
	{
		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JLabel title = new JLabel("Cushty");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);

		// ---- Connection -----------------------------------------------------------------------
		testButton.addActionListener(e -> onTest.run());
		testButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		testButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel connectionBody = new JPanel();
		connectionBody.setLayout(new BoxLayout(connectionBody, BoxLayout.Y_AXIS));
		connectionBody.setOpaque(false);
		connectionBody.add(testButton);
		connectionBody.add(Box.createVerticalStrut(4));
		connectionBody.add(status);

		// ---- Manual screenshots ---------------------------------------------------------------
		JLabel captionLabel = new JLabel("Caption (optional)");
		captionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		captionLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		caption.setLineWrap(true);
		caption.setWrapStyleWord(true);
		caption.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		caption.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		JScrollPane captionScroll = new JScrollPane(caption);
		captionScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		captionScroll.setAlignmentX(Component.LEFT_ALIGNMENT);
		captionScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 72));

		sendButton.addActionListener(e -> onSend.accept(caption()));
		snipButton.addActionListener(e -> onSnip.run());

		JPanel shotButtons = new JPanel(new GridLayout(0, 1, 0, 6));
		shotButtons.add(sendButton);
		shotButtons.add(snipButton);
		shotButtons.setAlignmentX(Component.LEFT_ALIGNMENT);
		shotButtons.setMaximumSize(new Dimension(Integer.MAX_VALUE, 64));

		JPanel manualBody = new JPanel();
		manualBody.setLayout(new BoxLayout(manualBody, BoxLayout.Y_AXIS));
		manualBody.setOpaque(false);
		manualBody.add(captionLabel);
		manualBody.add(Box.createVerticalStrut(4));
		manualBody.add(captionScroll);
		manualBody.add(Box.createVerticalStrut(6));
		manualBody.add(shotButtons);

		// ---- Bingo ----------------------------------------------------------------------------
		refreshBingoButton.addActionListener(e -> onRefreshBingo.run());
		bingoBoard.setEditable(false);
		bingoBoard.setLineWrap(true);
		bingoBoard.setWrapStyleWord(true);
		bingoBoard.setFont(FontManager.getRunescapeSmallFont());
		bingoBoard.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bingoBoard.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		bingoBoard.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		bingoBoard.setText(
			"Turn on Bingo in settings, then refresh.\n\n"
				+ "Drops for your team's tiles are posted automatically.");
		JScrollPane bingoScroll = new JScrollPane(bingoBoard);
		bingoScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		bingoScroll.setAlignmentX(Component.LEFT_ALIGNMENT);

		refreshBingoButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		refreshBingoButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

		JPanel bingoBody = new JPanel();
		bingoBody.setLayout(new BoxLayout(bingoBody, BoxLayout.Y_AXIS));
		bingoBody.setOpaque(false);
		bingoBody.add(refreshBingoButton);
		bingoBody.add(Box.createVerticalStrut(6));
		bingoBody.add(bingoScroll);

		JPanel stack = new JPanel();
		stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
		stack.setOpaque(false);
		stack.add(title);
		stack.add(Box.createVerticalStrut(10));
		stack.add(section("Connection", connectionBody));
		stack.add(Box.createVerticalStrut(10));
		stack.add(section("Manual screenshots", manualBody));
		stack.add(Box.createVerticalStrut(10));
		stack.add(section("Bingo", bingoBody));

		JScrollPane outer = new JScrollPane(stack);
		outer.setBorder(BorderFactory.createEmptyBorder());
		outer.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		outer.getVerticalScrollBar().setUnitIncrement(16);
		add(outer, BorderLayout.CENTER);
	}

	private static JPanel section(String name, JComponent body)
	{
		JLabel label = new JLabel(name);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);

		body.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel wrap = new JPanel();
		wrap.setLayout(new BoxLayout(wrap, BoxLayout.Y_AXIS));
		wrap.setOpaque(false);
		wrap.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrap.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(0, 0, 8, 0)));
		wrap.add(label);
		wrap.add(Box.createVerticalStrut(6));
		wrap.add(body);
		return wrap;
	}

	/** Label for the non-snip button. Matches the capture-area setting. Safe from any thread. */
	void setSendLabel(String label)
	{
		SwingUtilities.invokeLater(() -> sendButton.setText(label));
	}

	/** Safe to call from any thread. */
	void setStatus(String message, boolean error)
	{
		SwingUtilities.invokeLater(() ->
			showStatus(message, error ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.PROGRESS_COMPLETE_COLOR));
	}

	/** Neutral status, for snip instructions. Safe to call from any thread. */
	void setHint(String message)
	{
		SwingUtilities.invokeLater(() -> showStatus(message, ColorScheme.LIGHT_GRAY_COLOR));
	}

	/** Safe to call from any thread. */
	void setBusy(boolean busy)
	{
		SwingUtilities.invokeLater(() ->
		{
			this.busy = busy;
			refreshButtons();
		});
	}

	/** Safe to call from any thread. */
	void setSnipping(boolean snipping)
	{
		SwingUtilities.invokeLater(() ->
		{
			this.snipping = snipping;
			refreshButtons();
		});
	}

	/** Call on the Swing thread. */
	String caption()
	{
		String text = caption.getText().trim();
		return text.length() > MAX_CAPTION ? text.substring(0, MAX_CAPTION) : text;
	}

	/** Safe to call from any thread. */
	void clearCaption()
	{
		SwingUtilities.invokeLater(() -> caption.setText(""));
	}

	/** Safe to call from any thread. */
	void showBingoBoard(BingoModels.Board board, BingoModels.History history)
	{
		SwingUtilities.invokeLater(() ->
		{
			bingoBoard.setText(BingoFormat.formatBoard(board, history));
			bingoBoard.setCaretPosition(0);
		});
	}

	/** Safe to call from any thread. */
	void showBingoMessage(String message)
	{
		SwingUtilities.invokeLater(() -> bingoBoard.setText(message));
	}

	private void refreshButtons()
	{
		sendButton.setEnabled(!busy && !snipping);
		snipButton.setEnabled(!busy);
		snipButton.setText(snipping ? "Cancel snip" : "Snip");
		testButton.setEnabled(!busy && !snipping);
		refreshBingoButton.setEnabled(!busy && !snipping);
	}

	private void showStatus(String message, Color color)
	{
		status.setText("<html>" + escape(message) + "</html>");
		status.setForeground(color);
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

