import net.runelite.http.api.loottracker.LootRecordType;
import okhttp3.HttpUrl;

@Slf4j
@PluginDescriptor(
	name = "Cushty",
	description = "Share your drops, pets, bingo progress, and game-view screenshots with a clan Discord you configure",
	tags = {"discord", "screenshot", "clan", "drops", "loot", "pet", "bingo"}
)
public class CushtyPlugin extends Plugin
{
	/** Keep in line with the bot's MAX_UPLOAD_MB default. */
	private static final int MAX_UPLOAD_BYTES = 8 * 1024 * 1024;
	/** Wait a couple of ticks so the pet and the clan broadcast are visible in the shot. */
	private static final int PET_CAPTURE_DELAY_TICKS = 2;
	/** Refresh bingo watchlist from the server on this tick interval (~5 min at 0.6s/tick). */
	private static final int BINGO_WATCHLIST_TICKS = 500;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CushtyConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScreenshotCapture screenshotCapture;

	@Inject
	private PrivateChatRedactor privateChat;

	@Inject
	private SnipSelector snipSelector;

	@Inject
	private CushtyApiClient api;

	private CushtyPanel panel;
	private NavigationButton navButton;
	private EventPayload pendingPet;
	private int pendingPetTicks;
	/** Snip was requested and the mouse grab has not been installed yet. */
	private volatile boolean snipPending;
	/** Bingo watchlist from the server: item id → display name. */
	private volatile Map<Integer, String> bingoWatchById = Map.of();
	private int bingoWatchlistTicks;

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.screenshotHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			sendManual(null, false, null);
		}
	};

	@Provides
	CushtyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CushtyConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new CushtyPanel(
			caption -> sendManual(caption, true, null),
			this::onSnipButton,
			this::testConnection,
			this::refreshBingoBoard);
		panel.setSendLabel(config.captureArea().buttonLabel());
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Cushty")
			.icon(icon)
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		keyManager.registerKeyListener(hotkeyListener);
		keyManager.registerKeyListener(snipSelector.keys());
		snipSelector.registerMouse();
		bingoWatchlistTicks = 0;
		refreshBingoWatchlist();
	}

	@Override
	protected void shutDown()
	{
		snipPending = false;
		snipSelector.dismiss();
		screenshotCapture.releaseRedaction();
		keyManager.unregisterKeyListener(hotkeyListener);
		keyManager.unregisterKeyListener(snipSelector.keys());
		snipSelector.unregisterMouse();
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		pendingPet = null;
		bingoWatchById = Map.of();
	}

	// ---- Manual screenshots -------------------------------------------------------------------

	private void onSnipButton()
	{
		if (snipSelector.isActive() || snipPending)
		{
			snipPending = false;
			if (snipSelector.isActive())
			{
				snipSelector.cancel();
			}
			else
			{
				onSnipCancel();
			}
			return;
		}
		if (!config.manualEnabled())
		{
			report("Turn on 'Enable manual screenshots' in the Cushty settings first.", true);
			return;
		}
		if (!configured())
		{
			report("Set an HTTPS server URL and token in the Cushty settings.", true);
			return;
		}
		snipPending = true;
		CushtyPanel current = panel;
		if (current != null)
		{
			current.setSnipping(true);
			current.setHint("Drag a box on the game view. Esc cancels.");
		}
		// Register the mouse grab on the client thread, outside mouse dispatch.
		clientThread.invokeLater(() ->
		{
			if (!snipPending)
			{
				return;
			}
			snipPending = false;
			snipSelector.start(this::onSnipReady, this::onSnipCancel, this::onSnipHint);
		});
	}

	private void onSnipReady(Rectangle area)
	{
		SwingUtilities.invokeLater(() ->
		{
			CushtyPanel current = panel;
			if (current == null)
			{
				return;
			}
			current.setSnipping(false);
			sendManual(current.caption(), true, area);
		});
	}

	private void onSnipCancel()
	{
		CushtyPanel current = panel;
		if (current != null)
		{
			current.setSnipping(false);
			current.setHint("Snip cancelled.");
		}
	}

	private void onSnipHint(String message)
	{
		CushtyPanel current = panel;
		if (current != null)
		{
			current.setHint(message);
		}
	}

	private void sendManual(String caption, boolean fromPanel, Rectangle snip)
	{
		if (!config.manualEnabled())
		{
			report("Turn on 'Enable manual screenshots' in the Cushty settings first.", true);
			return;
		}
		EventPayload payload = EventPayload.builder()
			.type(EventPayload.TYPE_MANUAL)
			.caption(caption == null || caption.isBlank() ? null : caption)
			.build();
		send(payload, fromPanel, snip);
	}

	private boolean configured()
	{
		HttpUrl server = CushtyApiClient.parseServerUrl(config.serverUrl());
		return server != null && !config.token().trim().isEmpty();
	}

	private static String failureMessage(Throwable error)
	{
		Throwable cause = error;
		while ((cause instanceof CompletionException || cause instanceof ExecutionException) && cause.getCause() != null)
		{
			cause = cause.getCause();
		}
		if (cause instanceof CaptureException)
		{
			return cause.getMessage();
		}
		return "Could not capture a screenshot";
	}

	private void testConnection()
	{
		HttpUrl server = CushtyApiClient.parseServerUrl(config.serverUrl());
		String token = config.token().trim();
		if (server == null || token.isEmpty())
		{
			report("Set an HTTPS server URL and token first.", true);
			return;
		}
		api.checkConnection(server, token, listener(false));
	}

	// ---- Valuable drops -----------------------------------------------------------------------

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		handleLoot(event.getNpc().getName(), event.getItems());
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		handleLoot(event.getPlayer().getName(), event.getItems());
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		// NPC/player kills use the handlers above. EVENT/PICKPOCKET/UNKNOWN cover chests,
		// raids, reward pools, and odd sources the loot tracker does not classify.
		LootRecordType type = event.getType();
		if (type == LootRecordType.EVENT
			|| type == LootRecordType.PICKPOCKET
			|| type == LootRecordType.UNKNOWN)
		{
			handleLoot(event.getName(), event.getItems());
		}
	}

	private void handleLoot(String source, Collection<ItemStack> items)
	{
		boolean lootOn = config.lootEnabled();
		boolean bingoOn = config.bingoEnabled();
		if ((!lootOn && !bingoOn) || items.isEmpty())
		{
			return;
		}

		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		for (ItemStack stack : items)
		{
			quantities.merge(itemManager.canonicalize(stack.getId()), stack.getQuantity(), Integer::sum);
		}

		List<EventPayload.LootItem> drop = new ArrayList<>(quantities.size());
		quantities.forEach((id, quantity) -> drop.add(new EventPayload.LootItem(
			id,
			itemManager.getItemComposition(id).getName(),
			quantity,
			itemManager.getItemPrice(id))));

		Map<Integer, String> watchMap = bingoOn ? bingoWatchById : Map.of();
		// Valuable-drop threshold only applies when loot is enabled; bingo-only mode still
		// submits watchlist hits under 5M.
		long minValue = lootOn ? config.lootMinValue() : Long.MAX_VALUE;
		LootFilter filter = new LootFilter(minValue, watchMap.keySet());
		LootFilter.Result result = filter.select(drop);
		if (result.isEmpty())
		{
			if (bingoOn)
			{
				log.debug("Loot ignored (not valuable / not on bingo watchlist of {}): {}",
					watchMap.size(), quantities.keySet());
			}
			return;
		}

		String name = source == null || source.isBlank() ? "Unknown" : Text.removeTags(source);
		send(EventPayload.builder()
			.type(EventPayload.TYPE_LOOT)
			.loot(new EventPayload.Loot(name, result.getItems(), result.getTotalValue()))
			.build(), false, null);
	}

	/** Aerial fishing etc. announce {@code Untradeable drop: X} without a usable loot event. */
	private void handleUntradeableBingoDrop(String itemName)
	{
		Integer itemId = findWatchIdByName(itemName);
		if (itemId == null)
		{
			log.debug("Untradeable drop '{}' not on bingo watchlist ({} items)",
				itemName, bingoWatchById.size());
			return;
		}
		long price = itemManager.getItemPrice(itemId);
		String name = bingoWatchById.getOrDefault(itemId, itemName);
		send(EventPayload.builder()
			.type(EventPayload.TYPE_LOOT)
			.loot(new EventPayload.Loot(
				name,
				List.of(new EventPayload.LootItem(itemId, name, 1, price)),
				Math.max(price, 0)))
			.build(), false, null);
	}

	private Integer findWatchIdByName(String itemName)
	{
		for (Map.Entry<Integer, String> entry : bingoWatchById.entrySet())
		{
			if (entry.getValue() != null && entry.getValue().equalsIgnoreCase(itemName))
			{
				return entry.getKey();
			}
		}
		return null;
	}

	/**
	 * If bingo is on, try to map the new follower NPC to a watchlist pet item so the
	 * server can auto-count OR-tiles that include pets.
	 */
	private void attachBingoPetItem(EventPayload payload)
	{
		if (!config.bingoEnabled() || bingoWatchById.isEmpty() || payload.getPet() == null)
		{
			return;
		}
		NPC follower = client.getFollower();
		if (follower == null || follower.getName() == null)
		{
			return;
		}
		String petName = Text.removeTags(follower.getName());
		Integer itemId = findWatchIdByName(petName);
		if (itemId == null)
		{
			// Common board labels include a "Pet " prefix while the NPC name may not (or vice versa).
			itemId = findWatchIdByName("Pet " + petName);
		}
		if (itemId == null && petName.regionMatches(true, 0, "Pet ", 0, 4))
		{
			itemId = findWatchIdByName(petName.substring(4).trim());
		}
		if (itemId == null)
		{
			log.debug("Bingo: pet follower '{}' not on watchlist", petName);
			return;
		}
		String watchName = bingoWatchById.getOrDefault(itemId, petName);
		payload.getPet().setItemId(itemId);
		payload.getPet().setItemName(watchName);
		log.debug("Bingo: pet matched watchlist {} ({})", watchName, itemId);
	}

	// ---- Pets + bingo chat --------------------------------------------------------------------

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());

		if (config.bingoEnabled() && !bingoWatchById.isEmpty())
		{
			String dropName = UntradeableDrops.parseItemName(message);
			if (dropName != null)
			{
				handleUntradeableBingoDrop(dropName);
			}
		}

		if (!config.petsEnabled())
		{
			return;
		}
		PetMessages.Result result = PetMessages.classify(message);
		if (result == PetMessages.Result.NONE)
		{
			return;
		}
		pendingPet = EventPayload.builder()
			.type(EventPayload.TYPE_PET)
			.pet(new EventPayload.Pet(result == PetMessages.Result.DUPLICATE, message))
			.build();
		pendingPetTicks = PET_CAPTURE_DELAY_TICKS;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (pendingPet != null && --pendingPetTicks <= 0)
		{
			EventPayload pet = pendingPet;
			pendingPet = null;
			attachBingoPetItem(pet);
			send(pet, false, null);
		}
		if (config.bingoEnabled() && --bingoWatchlistTicks <= 0)
		{
			bingoWatchlistTicks = BINGO_WATCHLIST_TICKS;
			refreshBingoWatchlist();
		}
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		privateChat.onScriptCallback(event, client);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CushtyConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("captureArea".equals(event.getKey()))
		{
			CushtyPanel current = panel;
			if (current != null)
			{
				current.setSendLabel(config.captureArea().buttonLabel());
			}
		}
		if ("bingoEnabled".equals(event.getKey()))
		{
			if (config.bingoEnabled())
			{
				bingoWatchlistTicks = 0;
				refreshBingoWatchlist();
				refreshBingoBoard();
			}
			else
			{
				bingoWatchById = Map.of();
				CushtyPanel current = panel;
				if (current != null)
				{
					current.showBingoMessage("Bingo is turned off in settings.");
				}
			}
		}
	}

	private void refreshBingoWatchlist()
	{
		if (!config.bingoEnabled())
		{
			bingoWatchById = Map.of();
			return;
		}
		HttpUrl server = CushtyApiClient.parseServerUrl(config.serverUrl());
		String token = config.token().trim();
		if (server == null || token.isEmpty())
		{
			return;
		}
		api.fetchWatchlist(server, token, new CushtyApiClient.ValueListener<BingoModels.Watchlist>()
		{
			@Override
			public void onSuccess(BingoModels.Watchlist value)
			{
				if (value == null || value.getItems() == null || value.getItems().isEmpty())
				{
					bingoWatchById = Map.of();
					log.debug("Bingo watchlist empty (active={}, teamId={})",
						value != null && value.isActive(),
						value != null ? value.getTeamId() : null);
					return;
				}
				Map<Integer, String> next = new LinkedHashMap<>();
				for (BingoModels.WatchItem item : value.getItems())
				{
					if (item != null)
					{
						next.put(item.getId(), item.getName() != null ? item.getName() : ("Item " + item.getId()));
					}
				}
				bingoWatchById = Collections.unmodifiableMap(next);
				log.debug("Bingo watchlist loaded: {} item(s)", bingoWatchById.size());
			}

			@Override
			public void onFailure(String message)
			{
				log.debug("Bingo watchlist refresh failed: {}", message);
			}
		});
	}

	private void refreshBingoBoard()
	{
		if (!config.bingoEnabled())
		{
			CushtyPanel current = panel;
			if (current != null)
			{
				current.showBingoMessage("Turn on Bingo in the Cushty settings.");
			}
			return;
		}
		HttpUrl server = CushtyApiClient.parseServerUrl(config.serverUrl());
		String token = config.token().trim();
		if (server == null || token.isEmpty())
		{
			report("Set an HTTPS server URL and token first.", true);
			return;
		}
		api.fetchBoard(server, token, new CushtyApiClient.ValueListener<BingoModels.Board>()
		{
			@Override
			public void onSuccess(BingoModels.Board board)
			{
				api.fetchHistory(server, token, 40, new CushtyApiClient.ValueListener<BingoModels.History>()
				{
					@Override
					public void onSuccess(BingoModels.History history)
					{
						CushtyPanel current = panel;
						if (current != null)
						{
							current.showBingoBoard(board, history);
						}
						refreshBingoWatchlist();
					}

					@Override
					public void onFailure(String message)
					{
						CushtyPanel current = panel;
						if (current != null)
						{
							// Board still useful even if history fails.
							current.showBingoBoard(board, null);
						}
						refreshBingoWatchlist();
						log.debug("Bingo history refresh failed: {}", message);
					}
				});
			}

			@Override
			public void onFailure(String message)
			{
				CushtyPanel current = panel;
				if (current != null)
				{
					current.showBingoMessage(message);
				}
			}
		});
	}

	// ---- Sending ------------------------------------------------------------------------------

	/**
	 * Captures the next frame and posts it. Safe to call from any thread.
	 *
	 * @param fromPanel whether the sidebar panel should show progress and clear its caption
	 */
	private void send(EventPayload payload, boolean fromPanel, Rectangle snip)
	{
		// A selection box would be drawn into the next frame, so drop snip mode before capturing.
		if (snipSelector.isActive() || snipPending)
		{
			snipPending = false;
			snipSelector.dismiss();
			CushtyPanel snipPanel = panel;
			if (snipPanel != null)
			{
				snipPanel.setSnipping(false);
			}
		}

		final HttpUrl server = CushtyApiClient.parseServerUrl(config.serverUrl());
		final String token = config.token().trim();
		if (server == null || token.isEmpty())
		{
			report("Set an HTTPS server URL and token in the Cushty settings.", true);
			return;
		}

		CushtyPanel currentPanel = panel;
		if (fromPanel && currentPanel != null)
		{
			currentPanel.setBusy(true);
		}

		clientThread.invokeLater(() ->
		{
			Player player = client.getLocalPlayer();
			if (config.includeRsn() && player != null && player.getName() != null)
			{
				payload.setRsn(Text.sanitize(player.getName()));
			}
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				payload.setWorld(client.getWorld());
			}

			CushtyApiClient.ResultListener listener = listener(fromPanel);
			boolean chatbox = snip == null && config.captureArea() == CaptureArea.CHATBOX;
			screenshotCapture.capture(snip, chatbox, config.hidePrivateChat())
				.whenComplete((png, error) ->
				{
					if (error != null)
					{
						log.debug("Screenshot capture failed", error);
						listener.onFailure(failureMessage(error));
					}
					else if (png.length > MAX_UPLOAD_BYTES)
					{
						listener.onFailure("Screenshot is too large to upload");
					}
					else
					{
						api.sendEvent(server, token, payload, png, listener);
					}
				});
		});
	}

	private CushtyApiClient.ResultListener listener(boolean fromPanel)
	{
		return new CushtyApiClient.ResultListener()
		{
			@Override
			public void onSuccess(String message)
			{
				finish(message, false);
			}

			@Override
			public void onFailure(String message)
			{
				finish(message, true);
			}

			private void finish(String message, boolean error)
			{
				CushtyPanel current = panel;
				if (fromPanel && current != null)
				{
					current.setBusy(false);
					if (!error)
					{
						current.clearCaption();
					}
				}
				report(message, error);
			}
		};
	}

	/** Shows a status message in the panel and, if enabled, in game chat. Safe from any thread. */
	private void report(String message, boolean error)
	{
		CushtyPanel current = panel;
		if (current != null)
		{
			current.setStatus(message, error);
		}
		if (!config.chatNotifications())
		{
			return;
		}
		String formatted = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[Cushty] ")
			.append(ChatColorType.NORMAL)
			.append(message)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}
}

package com.cushty.api;

import java.util.Collections;
import java.util.List;
import lombok.Data;

/** JSON shapes for {@code GET /v1/bingo/*}. Unknown fields are ignored by Gson. */
public final class BingoModels
{
	private BingoModels()
	{
	}

	@Data
	public static class Watchlist
	{
		private boolean active;
		private Integer eventId;
		private String eventName;
		private Integer teamId;
		private String teamName;
		private List<WatchItem> items = Collections.emptyList();
	}

	@Data
	public static class WatchItem
	{
		private int id;
		private String name;
	}

	@Data
	public static class Board
	{
		private int eventId;
		private String eventName;
		private int teamId;
		private String teamName;
		private int width;
		private int height;
		private List<Tile> tiles = Collections.emptyList();
	}

	@Data
	public static class Tile
	{
		private int tileId;
		private String name;
		private int x;
		private int y;
		private boolean complete;
		private List<TileGroup> groups = Collections.emptyList();
	}

	@Data
	public static class TileGroup
	{
		/** {@code all} (AND) or {@code pool} (any N of these items). */
		private String mode = "all";
		private Integer poolQty;
		private List<TileItem> items = Collections.emptyList();
	}

	@Data
	public static class TileItem
	{
		private int itemId;
		private String itemName;
		private int requiredQty;
		private int progress;
	}

	@Data
	public static class History
	{
		private int eventId;
		private String eventName;
		private int teamId;
		private String teamName;
		private List<HistoryEntry> entries = Collections.emptyList();
	}

	@Data
	public static class HistoryEntry
	{
		private int id;
		private int tileId;
		private String tileName;
		private int x;
		private int y;
		private int itemId;
		private String itemName;
		private int quantity;
		private String status;
		private String source;
		private String discordId;
		private long createdAt;
		private Long reversedAt;
		private String reversedBy;
	}
}

package com.cushty.api;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the configured server. All calls are asynchronous on the OkHttp thread pool; callbacks are
 * invoked on that pool too, never on the client thread.
 */
@Slf4j
@Singleton
public class CushtyApiClient
{
	private static final MediaType PNG = MediaType.parse("image/png");

	private final OkHttpClient http;
	private final Gson gson;

	@Inject
	CushtyApiClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	public interface ResultListener
	{
		void onSuccess(String message);

		void onFailure(String message);
	}

	public interface ValueListener<T>
	{
		void onSuccess(T value);

		void onFailure(String message);
	}

	/**
	 * Validates the configured server URL. HTTPS is required so tokens and screenshots are never
	 * sent in the clear; plain HTTP is only allowed for a bot running on this machine.
	 *
	 * @return the parsed URL, or null if it is unusable
	 */
	public static HttpUrl parseServerUrl(String value)
	{
		if (value == null || value.isBlank())
		{
			return null;
		}
		HttpUrl url = HttpUrl.parse(value.trim());
		if (url == null)
		{
			return null;
		}
		boolean local = url.host().equals("localhost") || url.host().equals("127.0.0.1");
		return url.isHttps() || local ? url : null;
	}

	public void sendEvent(HttpUrl server, String token, EventPayload payload, byte[] png, ResultListener listener)
	{
		RequestBody body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload", gson.toJson(payload))
			.addFormDataPart("screenshot", "screenshot.png", RequestBody.create(PNG, png))
			.build();

		Request request = new Request.Builder()
			.url(server.newBuilder().addPathSegments("v1/events").build())
			.header("Authorization", "Bearer " + token)
			.post(body)
			.build();

		execute(request, listener, json -> listener.onSuccess("Posted to Discord"));
	}

	public void checkConnection(HttpUrl server, String token, ResultListener listener)
	{
		Request request = new Request.Builder()
			.url(server.newBuilder().addPathSegments("v1/me").build())
			.header("Authorization", "Bearer " + token)
			.get()
			.build();

		execute(request, listener, json ->
		{
			String name = json != null && json.has("displayName") ? json.get("displayName").getAsString() : "unknown";
			listener.onSuccess("Connected as " + name);
		});
	}

	public void fetchWatchlist(HttpUrl server, String token, ValueListener<BingoModels.Watchlist> listener)
	{
		Request request = new Request.Builder()
			.url(server.newBuilder().addPathSegments("v1/bingo/watchlist").build())
			.header("Authorization", "Bearer " + token)
			.get()
			.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Bingo watchlist request failed", e);
				listener.onFailure("Could not reach the Cushty server");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					if (response.code() == 404)
					{
						// Bot without bingo enabled.
						BingoModels.Watchlist empty = new BingoModels.Watchlist();
						empty.setActive(false);
						listener.onSuccess(empty);
						return;
					}
					String raw = responseBody != null ? responseBody.string() : null;
					if (!response.isSuccessful())
					{
						listener.onFailure(messageFrom(raw, response.code()));
						return;
					}
					BingoModels.Watchlist watchlist = gson.fromJson(raw, BingoModels.Watchlist.class);
					listener.onSuccess(watchlist != null ? watchlist : new BingoModels.Watchlist());
				}
				catch (IOException | JsonParseException e)
				{
					listener.onFailure("Could not read bingo watchlist");
				}
			}
		});
	}

	public void fetchBoard(HttpUrl server, String token, ValueListener<BingoModels.Board> listener)
	{
		getJson(server, token, "v1/bingo/board", BingoModels.Board.class, listener, "bingo board");
	}

	public void fetchHistory(HttpUrl server, String token, int limit, ValueListener<BingoModels.History> listener)
	{
		HttpUrl url = server.newBuilder()
			.addPathSegments("v1/bingo/history")
			.addQueryParameter("limit", String.valueOf(limit))
			.build();
		Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.get()
			.build();
		getJson(request, BingoModels.History.class, listener, "bingo history");
	}

	private <T> void getJson(
		HttpUrl server,
		String token,
		String path,
		Class<T> type,
		ValueListener<T> listener,
		String label)
	{
		Request request = new Request.Builder()
			.url(server.newBuilder().addPathSegments(path).build())
			.header("Authorization", "Bearer " + token)
			.get()
			.build();
		getJson(request, type, listener, label);
	}

	private <T> void getJson(Request request, Class<T> type, ValueListener<T> listener, String label)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Bingo {} request failed", label, e);
				listener.onFailure("Could not reach the Cushty server");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					String raw = responseBody != null ? responseBody.string() : null;
					if (!response.isSuccessful())
					{
						listener.onFailure(messageFrom(raw, response.code()));
						return;
					}
					T value = gson.fromJson(raw, type);
					if (value == null)
					{
						listener.onFailure("Empty " + label + " response");
						return;
					}
					listener.onSuccess(value);
				}
				catch (IOException | JsonParseException e)
				{
					listener.onFailure("Could not read " + label);
				}
			}
		});
	}

	private void execute(Request request, ResultListener listener, Consumer<JsonObject> onOk)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Cushty request failed", e);
				listener.onFailure("Could not reach the Cushty server");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					JsonObject json = parse(responseBody);
					if (response.isSuccessful())
					{
						onOk.accept(json);
						return;
					}
					String message = json != null && json.has("message")
						? json.get("message").getAsString()
						: "Server returned HTTP " + response.code();
					listener.onFailure(message);
				}
			}
		});
	}

	private JsonObject parse(ResponseBody body)
	{
		if (body == null)
		{
			return null;
		}
		try
		{
			return gson.fromJson(body.charStream(), JsonObject.class);
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}

	private String messageFrom(String raw, int code)
	{
		if (raw != null && !raw.isBlank())
		{
			try
			{
				JsonObject json = gson.fromJson(raw, JsonObject.class);
				if (json != null && json.has("message"))
				{
					return json.get("message").getAsString();
				}
			}
			catch (JsonParseException ignored)
			{
				// fall through
			}
		}
		return "Server returned HTTP " + code;
	}
}

package com.cushty.api;

import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * JSON body of {@code POST /v1/events}. Fields are {@code type}, optional {@code rsn},
 * {@code caption} and {@code world}, plus {@code loot} or {@code pet}. Nulls are omitted.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class EventPayload
{
	public static final String TYPE_MANUAL = "manual";
	public static final String TYPE_LOOT = "loot";
	public static final String TYPE_PET = "pet";

	private String type;
	private String rsn;
	private String caption;
	private Integer world;
	private Loot loot;
	private Pet pet;

	@Data
	@AllArgsConstructor
	public static class Loot
	{
		private String source;
		private List<LootItem> items;
		private long totalValue;
	}

	@Data
	@AllArgsConstructor
	public static class LootItem
	{
		private int id;
		private String name;
		private int quantity;
		private long priceEach;

		public long stackValue()
		{
			return priceEach * quantity;
		}
	}

	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class Pet
	{
		private boolean duplicate;
		private String message;
		/** Set when bingo matched the pet to a watchlist item (follower NPC name). */
		private Integer itemId;
		private String itemName;

		public Pet(boolean duplicate, String message)
		{
			this.duplicate = duplicate;
			this.message = message;
		}
	}
}

