package com.cushty.capture;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;

/** Geometry for cropping a game-canvas screenshot. Coordinates are canvas pixels, not stretched pixels. */
final class CaptureFrames
{
	private static final int MIN_PART = 8;

	private CaptureFrames()
	{
	}

	static Rectangle fromPoints(Point a, Point b)
	{
		int x = Math.min(a.x, b.x);
		int y = Math.min(a.y, b.y);
		return new Rectangle(x, y, Math.abs(a.x - b.x), Math.abs(a.y - b.y));
	}

	/**
	 * A widget is part of the chatbox when it has a real size and is not the full game view.
	 * Some parent widgets report bounds that cover the whole canvas.
	 */
	static boolean include(Rectangle part, int spaceWidth, int spaceHeight)
	{
		if (part == null || spaceWidth <= 0 || spaceHeight <= 0)
		{
			return false;
		}
		if (part.width < MIN_PART || part.height < MIN_PART)
		{
			return false;
		}
		boolean coversWidth = part.width > spaceWidth * 0.95;
		boolean coversHeight = part.height > spaceHeight * 0.95;
		return !(coversWidth && coversHeight);
	}

	static Rectangle union(Rectangle... parts)
	{
		Rectangle union = null;
		for (Rectangle part : parts)
		{
			if (part == null)
			{
				continue;
			}
			union = union == null ? new Rectangle(part) : union.union(part);
		}
		return union;
	}

	/** Map a canvas rectangle onto a screenshot, which may be stretched or scaled for the display. */
	static Rectangle scale(Rectangle canvas, int imageWidth, int imageHeight, int spaceWidth, int spaceHeight)
	{
		if (canvas == null || imageWidth <= 0 || imageHeight <= 0 || spaceWidth <= 0 || spaceHeight <= 0)
		{
			return null;
		}
		double scaleX = imageWidth / (double) spaceWidth;
		double scaleY = imageHeight / (double) spaceHeight;
		int x1 = clamp((int) Math.round(canvas.x * scaleX), 0, imageWidth);
		int y1 = clamp((int) Math.round(canvas.y * scaleY), 0, imageHeight);
		int x2 = clamp((int) Math.round((canvas.x + canvas.width) * scaleX), 0, imageWidth);
		int y2 = clamp((int) Math.round((canvas.y + canvas.height) * scaleY), 0, imageHeight);
		if (x2 < x1)
		{
			int swap = x1;
			x1 = x2;
			x2 = swap;
		}
		if (y2 < y1)
		{
			int swap = y1;
			y1 = y2;
			y2 = swap;
		}
		if (x2 <= x1 || y2 <= y1)
		{
			return null;
		}
		return new Rectangle(x1, y1, x2 - x1, y2 - y1);
	}

	static BufferedImage crop(BufferedImage image, Rectangle area)
	{
		if (area == null || area.width <= 0 || area.height <= 0)
		{
			return null;
		}
		if (area.x < 0 || area.y < 0 || area.x + area.width > image.getWidth() || area.y + area.height > image.getHeight())
		{
			return null;
		}
		return image.getSubimage(area.x, area.y, area.width, area.height);
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package com.cushty.capture;

import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Leaves private messages out of one drawn frame.
 * <p>
 * The chat builder asks plugins, via {@code chatFilterCheck}, whether each line should be
 * shown. While a capture is active we reject private messages and rebuild chat, so wrapped
 * lines disappear instead of leaving the text in place. The split private-chat window is a
 * separate widget, so it is hidden for the same frame. Call {@link #end} afterwards to put
 * both back. Login and logout lines are not private messages and stay.
 */
@Singleton
public class PrivateChatRedactor
{
	private final AtomicInteger depth = new AtomicInteger();
	private volatile boolean hidSplitPrivate;

	@Inject
	PrivateChatRedactor()
	{
	}

	public void onScriptCallback(ScriptCallbackEvent event, Client client)
	{
		if (depth.get() <= 0 || !"chatFilterCheck".equals(event.getEventName()))
		{
			return;
		}
		apply(client.getIntStack(), client.getIntStackSize());
	}

	/** Rebuild chat without private messages. Safe to nest; one matching {@link #end} restores it. */
	public void begin(Client client)
	{
		if (depth.getAndIncrement() == 0)
		{
			client.refreshChat();
			hideSplitPrivate(client);
		}
	}

	/** Put private messages back. Does nothing if {@link #begin} was not called. */
	public void end(Client client)
	{
		int left = depth.decrementAndGet();
		if (left > 0)
		{
			return;
		}
		if (left < 0)
		{
			depth.set(0);
			return;
		}
		client.refreshChat();
		showSplitPrivate(client);
	}

	/** Restore even if a capture was abandoned, such as the plugin shutting down. */
	public void forceEnd(Client client)
	{
		if (depth.getAndSet(0) > 0)
		{
			client.refreshChat();
			showSplitPrivate(client);
		}
	}

	static void apply(int[] intStack, int intStackSize)
	{
		// The chat script pushes the show flag, then the message type, then the message id.
		if (intStack == null || intStackSize < 3 || intStack.length < intStackSize)
		{
			return;
		}
		ChatMessageType type = ChatMessageType.of(intStack[intStackSize - 2]);
		if (isPrivate(type))
		{
			intStack[intStackSize - 3] = 0;
		}
	}

	static boolean isPrivate(ChatMessageType type)
	{
		return type == ChatMessageType.PRIVATECHAT
			|| type == ChatMessageType.PRIVATECHATOUT
			|| type == ChatMessageType.MODPRIVATECHAT;
	}

	private void hideSplitPrivate(Client client)
	{
		Widget pm = client.getWidget(InterfaceID.PmChat.CONTAINER);
		if (pm != null && !pm.isHidden())
		{
			pm.setHidden(true);
			hidSplitPrivate = true;
		}
	}

	private void showSplitPrivate(Client client)
	{
		if (!hidSplitPrivate)
		{
			return;
		}
		hidSplitPrivate = false;
		Widget pm = client.getWidget(InterfaceID.PmChat.CONTAINER);
		if (pm != null)
		{
			pm.setHidden(false);
		}
	}
}

package com.cushty.capture;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;

/**
 * Captures the next rendered game frame. This is the game canvas only: never the desktop, other
 * windows or the RuneLite sidebar. The image may then be cropped to the chatbox or a snipped area.
 */
@Singleton
public class ScreenshotCapture
{
	private static final int[] CHATBOX_PARTS = {
		InterfaceID.Chatbox.CHATAREA,
		InterfaceID.Chatbox.CHAT_BACKGROUND,
		InterfaceID.Chatbox.CHATDISPLAY,
		InterfaceID.Chatbox.SCROLLAREA,
		InterfaceID.Chatbox.INPUT,
		InterfaceID.Chatbox.CONTROLS
	};

	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;
	private final Client client;
	private final ClientThread clientThread;
	private final PrivateChatRedactor privateChat;

	@Inject
	ScreenshotCapture(
		DrawManager drawManager,
		ScheduledExecutorService executor,
		Client client,
		ClientThread clientThread,
		PrivateChatRedactor privateChat)
	{
		this.drawManager = drawManager;
		this.executor = executor;
		this.client = client;
		this.clientThread = clientThread;
		this.privateChat = privateChat;
	}

	/**
	 * @param snip canvas rectangle for a manual snip, or null to use {@code chatbox} / the full frame
	 * @param chatbox when there is no snip, capture only the chatbox
	 * @param hidePrivateChat rebuild chat without private messages for the captured frame
	 * @return a future completed with PNG bytes, off the client thread
	 */
	public CompletableFuture<byte[]> capture(Rectangle snip, boolean chatbox, boolean hidePrivateChat)
	{
		CompletableFuture<byte[]> result = new CompletableFuture<>();
		AtomicBoolean aborted = new AtomicBoolean();
		AtomicBoolean armed = new AtomicBoolean();
		AtomicBoolean restored = new AtomicBoolean();
		// One restore per capture. The frame listener and the timeout can both ask for it.
		Runnable restore = () -> clientThread.invokeLater(() ->
		{
			if (armed.get() && restored.compareAndSet(false, true))
			{
				privateChat.end(client);
			}
		});
		// orTimeout does not cancel the original future, so a late frame must notice the timeout.
		CompletableFuture<byte[]> timed = result.orTimeout(10, TimeUnit.SECONDS);
		timed.whenComplete((png, error) ->
		{
			aborted.set(true);
			restore.run();
		});

		clientThread.invokeAtTickEnd(() ->
		{
			if (aborted.get())
			{
				return;
			}
			Rectangle crop = snip;
			if (crop == null && chatbox)
			{
				crop = chatboxBounds();
				if (crop == null)
				{
					result.completeExceptionally(new CaptureException("The chatbox is not visible"));
					return;
				}
			}
			if (aborted.get() || result.isDone())
			{
				return;
			}

			if (hidePrivateChat)
			{
				privateChat.begin(client);
				armed.set(true);
			}
			final Rectangle cropFinal = crop == null ? null : new Rectangle(crop);
			final Dimension space = coordinateSpace();
			boolean listening = false;
			try
			{
				drawManager.requestNextFrameListener(frame -> onFrame(frame, result, aborted, cropFinal, space, restore));
				listening = true;
			}
			finally
			{
				if (!listening)
				{
					restore.run();
				}
			}
		});
		return timed;
	}

	/** Put private chat back if a capture is still holding it, for example on shutdown. */
	public void releaseRedaction()
	{
		Runnable restore = () -> privateChat.forceEnd(client);
		if (client.isClientThread())
		{
			restore.run();
		}
		else
		{
			clientThread.invoke(restore);
		}
	}

	private void onFrame(
		Image frame,
		CompletableFuture<byte[]> result,
		AtomicBoolean aborted,
		Rectangle crop,
		Dimension space,
		Runnable restore)
	{
		try
		{
			if (aborted.get() || result.isDone())
			{
				return;
			}
			// The frame buffer may be reused by the renderer, so copy it before leaving this callback.
			BufferedImage copy = copy(frame);
			BufferedImage shot = copy;
			if (crop != null)
			{
				Rectangle scaled = CaptureFrames.scale(crop, copy.getWidth(), copy.getHeight(), space.width, space.height);
				shot = CaptureFrames.crop(copy, scaled);
				if (shot == null)
				{
					result.completeExceptionally(new CaptureException("Could not capture that area"));
					return;
				}
			}
			BufferedImage finalShot = shot;
			executor.execute(() ->
			{
				try
				{
					result.complete(encodePng(finalShot));
				}
				catch (IOException e)
				{
					result.completeExceptionally(e);
				}
			});
		}
		catch (Throwable t)
		{
			result.completeExceptionally(t);
		}
		finally
		{
			// Next client cycle, after this frame has been copied and before the next draw.
			restore.run();
		}
	}

	private Rectangle chatboxBounds()
	{
		Dimension space = coordinateSpace();
		Rectangle[] parts = new Rectangle[CHATBOX_PARTS.length];
		int count = 0;
		for (int id : CHATBOX_PARTS)
		{
			Widget widget = client.getWidget(id);
			if (widget == null || widget.isHidden())
			{
				continue;
			}
			Rectangle bounds = new Rectangle(widget.getBounds());
			if (!CaptureFrames.include(bounds, space.width, space.height))
			{
				continue;
			}
			parts[count++] = bounds;
		}
		if (count == 0)
		{
			return null;
		}
		Rectangle[] present = new Rectangle[count];
		System.arraycopy(parts, 0, present, 0, count);
		return CaptureFrames.union(present);
	}

	private Dimension coordinateSpace()
	{
		Dimension real = client.getRealDimensions();
		if (real != null && real.width > 0 && real.height > 0)
		{
			return real;
		}
		return new Dimension(Math.max(client.getCanvasWidth(), 1), Math.max(client.getCanvasHeight(), 1));
	}

	private static BufferedImage copy(Image frame)
	{
		BufferedImage image = new BufferedImage(frame.getWidth(null), frame.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = image.createGraphics();
		graphics.drawImage(frame, 0, 0, null);
		graphics.dispose();
		return image;
	}

	static byte[] encodePng(BufferedImage image) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		if (!ImageIO.write(image, "png", out))
		{
			throw new IOException("No PNG encoder available");
		}
		return out.toByteArray();
	}
}

package com.cushty.capture;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Drag a rectangle on the game view. The rectangle is drawn as an overlay and removed before
 * the screenshot is taken, so the border is not in the image.
 */
@Singleton
public class SnipSelector
{
	static final int MIN_SIZE = 8;

	private final Client client;
	private final OverlayManager overlayManager;
	private final MouseManager mouseManager;
	private final SnipOverlay overlay = new SnipOverlay();
	private final SnipMouse mouse = new SnipMouse();
	private final SnipKeys keys = new SnipKeys();

	private volatile boolean active;
	private volatile Point anchor;
	private volatile Rectangle selection;
	private Consumer<Rectangle> onReady;
	private Runnable onCancel;
	private Consumer<String> onHint;

	@Inject
	SnipSelector(Client client, OverlayManager overlayManager, MouseManager mouseManager)
	{
		this.client = client;
		this.overlayManager = overlayManager;
		this.mouseManager = mouseManager;
	}

	public KeyListener keys()
	{
		return keys;
	}

	public void registerMouse()
	{
		mouseManager.unregisterMouseListener(mouse);
		mouseManager.registerMouseListener(mouse);
	}

	public void unregisterMouse()
	{
		mouseManager.unregisterMouseListener(mouse);
	}

	public boolean isActive()
	{
		return active;
	}

	public void start(Consumer<Rectangle> onReady, Runnable onCancel, Consumer<String> onHint)
	{
		if (active)
		{
			return;
		}
		this.onReady = onReady;
		this.onCancel = onCancel;
		this.onHint = onHint;
		anchor = null;
		selection = null;
		active = true;
		// Sit in front of other mouse listeners so the drag is not also a game click.
		mouseManager.unregisterMouseListener(mouse);
		mouseManager.registerMouseListener(0, mouse);
		overlayManager.add(overlay);
	}

	/** Stop drawing and tell the caller the snip was cancelled. */
	public void cancel()
	{
		if (!active)
		{
			return;
		}
		stopVisuals();
		Runnable cancel = onCancel;
		if (cancel != null)
		{
			cancel.run();
		}
	}

	/** Stop drawing without a cancel notice. Used when another screenshot takes over. */
	public void dismiss()
	{
		if (!active)
		{
			return;
		}
		stopVisuals();
	}

	private void stopVisuals()
	{
		active = false;
		anchor = null;
		selection = null;
		overlayManager.remove(overlay);
	}

	private void finish(Rectangle area)
	{
		Consumer<Rectangle> ready = onReady;
		stopVisuals();
		if (ready != null)
		{
			ready.accept(area);
		}
	}

	private final class SnipOverlay extends Overlay
	{
		private SnipOverlay()
		{
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.ALWAYS_ON_TOP);
			setPriority(PRIORITY_HIGH);
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			Rectangle area = selection;
			if (!active || area == null)
			{
				return null;
			}
			Dimension canvas = canvasSize();
			graphics.setColor(new Color(0, 0, 0, 100));
			dimAround(graphics, canvas, area);
			graphics.setColor(new Color(255, 208, 64));
			graphics.setStroke(new BasicStroke(1));
			graphics.draw(area);
			return null;
		}
	}

	private final class SnipMouse extends MouseAdapter
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			if (!active || SwingUtilities.isMiddleMouseButton(event))
			{
				return event;
			}
			if (SwingUtilities.isLeftMouseButton(event))
			{
				anchor = event.getPoint();
				selection = new Rectangle(anchor.x, anchor.y, 0, 0);
			}
			else
			{
				cancel();
			}
			event.consume();
			return event;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent event)
		{
			if (!active || anchor == null || !SwingUtilities.isLeftMouseButton(event))
			{
				return event;
			}
			selection = CaptureFrames.fromPoints(anchor, event.getPoint());
			event.consume();
			return event;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent event)
		{
			if (!active || !SwingUtilities.isLeftMouseButton(event))
			{
				return event;
			}
			Rectangle area = selection;
			anchor = null;
			if (area == null || area.width < MIN_SIZE || area.height < MIN_SIZE)
			{
				selection = null;
				Consumer<String> hint = onHint;
				if (hint != null)
				{
					hint.accept("Drag a larger area.");
				}
			}
			else
			{
				finish(new Rectangle(area));
			}
			event.consume();
			return event;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent event)
		{
			if (!active || SwingUtilities.isMiddleMouseButton(event))
			{
				return event;
			}
			event.consume();
			return event;
		}
	}

	private final class SnipKeys implements KeyListener
	{
		@Override
		public void keyPressed(KeyEvent event)
		{
			if (active && event.getKeyCode() == KeyEvent.VK_ESCAPE)
			{
				event.consume();
				cancel();
			}
		}

		@Override
		public void keyReleased(KeyEvent event)
		{
		}

		@Override
		public void keyTyped(KeyEvent event)
		{
		}

		@Override
		public boolean isEnabledOnLoginScreen()
		{
			return true;
		}
	}

	private Dimension canvasSize()
	{
		Dimension real = client.getRealDimensions();
		if (real != null && real.width > 0 && real.height > 0)
		{
			return real;
		}
		return new Dimension(Math.max(client.getCanvasWidth(), 1), Math.max(client.getCanvasHeight(), 1));
	}

	private static void dimAround(Graphics2D graphics, Dimension canvas, Rectangle hole)
	{
		int right = hole.x + hole.width;
		int bottom = hole.y + hole.height;
		graphics.fillRect(0, 0, canvas.width, Math.max(0, hole.y));
		graphics.fillRect(0, bottom, canvas.width, Math.max(0, canvas.height - bottom));
		graphics.fillRect(0, hole.y, Math.max(0, hole.x), hole.height);
		graphics.fillRect(right, hole.y, Math.max(0, canvas.width - right), hole.height);
	}
}

package com.cushty.loot;

import com.cushty.api.EventPayload;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.Value;

/** Decides which items in a drop are worth sharing. Free of RuneLite types so it can be unit tested. */
public final class LootFilter
{
	public static final int MAX_ITEMS = 25;
	/** Hard floor so the valuable-drop threshold cannot be edited down to pocket change. */
	public static final int MIN_STACK_VALUE = 5_000_000;

	private final long minStackValue;
	private final Set<Integer> watchIds;

	public LootFilter(long minStackValue)
	{
		this(minStackValue, Set.of());
	}

	public LootFilter(long minStackValue, Collection<Integer> watchIds)
	{
		this.minStackValue = Math.max(minStackValue, MIN_STACK_VALUE);
		this.watchIds = watchIds == null || watchIds.isEmpty()
			? Set.of()
			: new HashSet<>(watchIds);
	}

	@Value
	public static class Result
	{
		List<EventPayload.LootItem> items;
		long totalValue;

		public boolean isEmpty()
		{
			return items.isEmpty();
		}
	}

	/**
	 * Returns the items to share, most valuable first. Bingo watchlist items are included even
	 * when under the gp threshold. The total value covers the whole drop, not just the selected items.
	 */
	public Result select(Collection<EventPayload.LootItem> drop)
	{
		long total = 0;
		List<EventPayload.LootItem> selected = new ArrayList<>();
		for (EventPayload.LootItem item : drop)
		{
			total += item.stackValue();
			if (item.stackValue() >= minStackValue || watchIds.contains(item.getId()))
			{
				selected.add(item);
			}
		}

		selected.sort(Comparator.comparingLong(EventPayload.LootItem::stackValue).reversed());
		if (selected.size() > MAX_ITEMS)
		{
			selected = new ArrayList<>(selected.subList(0, MAX_ITEMS));
		}
		return new Result(selected, total);
	}
}

package com.cushty.loot;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses the game's {@code Untradeable drop: Item name} chat line.
 * Aerial fishing (Molch pearls) and similar activities announce this way and often never
 * fire a loot-tracker {@code LootReceived} that Cushty would see.
 */
public final class UntradeableDrops
{
	private static final Pattern PATTERN = Pattern.compile(
		"^Untradeable drop:\\s*(.+)$",
		Pattern.CASE_INSENSITIVE);

	private UntradeableDrops()
	{
	}

	/** Returns the item name, or {@code null} if the message is not an untradeable-drop line. */
	public static String parseItemName(String plainChat)
	{
		if (plainChat == null || plainChat.isBlank())
		{
			return null;
		}
		Matcher match = PATTERN.matcher(plainChat.trim());
		return match.matches() ? match.group(1).trim() : null;
	}
}

package com.cushty.pets;

/** Recognises the game messages shown when a pet is rolled. */
public final class PetMessages
{
	public enum Result
	{
		NONE,
		NEW_PET,
		DUPLICATE
	}

	private static final String FOLLOWED = "You have a funny feeling like you're being followed";
	private static final String BACKPACK = "You feel something weird sneaking into your backpack";
	private static final String DUPLICATE = "You have a funny feeling like you would have been followed";

	private PetMessages()
	{
	}

	/** @param message the chat message with formatting tags already removed */
	public static Result classify(String message)
	{
		if (message == null)
		{
			return Result.NONE;
		}
		if (message.startsWith(DUPLICATE))
		{
			return Result.DUPLICATE;
		}
		if (message.startsWith(FOLLOWED) || message.startsWith(BACKPACK))
		{
			return Result.NEW_PET;
		}
		return Result.NONE;
	}
}

package com.cushty;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.cushty.api.BingoModels;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class BingoFormatTest
{
	@Test
	public void genericNameIsDetected()
	{
		assertTrue(BingoFormat.isGenericName("Tile 1", 1));
		assertTrue(BingoFormat.isGenericName("tile", 2));
		assertTrue(BingoFormat.isGenericName("", 1));
		assertFalse(BingoFormat.isGenericName("Molch pearls", 1));
		assertFalse(BingoFormat.isGenericName("Clue scroll tile", 3));
	}

	@Test
	public void prefersCustomNameOverRequirements()
	{
		BingoModels.Tile tile = tile("Aerial fishing", allGroup(item("Molch pearl", 1, 1)));
		assertEquals("#1 Aerial fishing", BingoFormat.tileLine(tile, 1));
	}

	@Test
	public void fallsBackToItemNameWhenTitleIsGeneric()
	{
		BingoModels.Tile tile = tile("Tile 1", allGroup(item("Molch pearl", 1, 1)));
		assertEquals("#1 Molch pearl", BingoFormat.tileLine(tile, 1));
	}

	@Test
	public void showsProgressForQtyRequirements()
	{
		BingoModels.Tile tile = tile("Tile 2", allGroup(item("Water Rune", 5, 2)));
		assertEquals("#2 2/5 Water Rune", BingoFormat.tileLine(tile, 2));
	}

	@Test
	public void orGroupsJoinWithOr()
	{
		BingoModels.Tile tile = new BingoModels.Tile();
		tile.setName("Tile");
		tile.setGroups(Arrays.asList(
			allGroup(item("Bandos chestplate", 1, 0)),
			allGroup(item("Bandos tassets", 1, 0))));
		assertEquals("#1 Bandos chestplate or Bandos tassets", BingoFormat.tileLine(tile, 1));
	}

	@Test
	public void poolGroupSummarizesAnyN()
	{
		BingoModels.TileGroup pool = new BingoModels.TileGroup();
		pool.setMode("pool");
		pool.setPoolQty(3);
		pool.setItems(Arrays.asList(
			item("Berserker ring", 1, 0),
			item("Seers ring", 1, 0),
			item("Warrior ring", 1, 0)));
		BingoModels.Tile tile = new BingoModels.Tile();
		tile.setName("Tile 20");
		tile.setGroups(Collections.singletonList(pool));
		assertEquals("#20 any 3 of: Berserker ring, Seers ring, Warrior ring", BingoFormat.tileLine(tile, 20));
	}

	@Test
	public void manualGenericTileSaysManual()
	{
		BingoModels.Tile tile = new BingoModels.Tile();
		tile.setName("Tile 3");
		tile.setGroups(Collections.emptyList());
		assertEquals("#3 manual", BingoFormat.tileLine(tile, 3));
	}

	@Test
	public void formatBoardUsesLabelsNotTileTile()
	{
		BingoModels.Board board = new BingoModels.Board();
		board.setEventName("Clan Bingo");
		board.setTeamName("Red");
		board.setWidth(2);
		board.setHeight(1);

		BingoModels.Tile a = tile("Tile 1", allGroup(item("Molch pearl", 1, 1)));
		a.setComplete(true);
		a.setX(0);
		a.setY(0);
		BingoModels.Tile b = tile("Clue scroll", Collections.emptyList());
		b.setX(1);
		b.setY(0);
		board.setTiles(Arrays.asList(a, b));

		String text = BingoFormat.formatBoard(board, null);
		assertTrue(text.contains("[x] #1 Molch pearl"));
		assertTrue(text.contains("[ ] #2 Clue scroll"));
		assertFalse(text.contains("Tile 1 - Tile 1"));
	}

	private static BingoModels.Tile tile(String name, BingoModels.TileGroup group)
	{
		return tile(name, Collections.singletonList(group));
	}

	private static BingoModels.Tile tile(String name, java.util.List<BingoModels.TileGroup> groups)
	{
		BingoModels.Tile tile = new BingoModels.Tile();
		tile.setName(name);
		tile.setGroups(groups);
		return tile;
	}

	private static BingoModels.TileGroup allGroup(BingoModels.TileItem item)
	{
		BingoModels.TileGroup group = new BingoModels.TileGroup();
		group.setMode("all");
		group.setItems(Collections.singletonList(item));
		return group;
	}

	private static BingoModels.TileItem item(String name, int required, int progress)
	{
		BingoModels.TileItem item = new BingoModels.TileItem();
		item.setItemName(name);
		item.setRequiredQty(required);
		item.setProgress(progress);
		item.setItemId(1);
		return item;
	}
}

