package com.cushty.api;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import com.google.gson.Gson;
import java.util.List;
import org.junit.Test;

public class CushtyApiClientTest
{
	@Test
	public void requiresHttpsExceptForLocalhost()
	{
		assertNotNull(CushtyApiClient.parseServerUrl("https://cushty.example.com"));
		assertNotNull(CushtyApiClient.parseServerUrl("  https://cushty.example.com/  "));
		assertNotNull(CushtyApiClient.parseServerUrl("http://localhost:8080"));
		assertNotNull(CushtyApiClient.parseServerUrl("http://127.0.0.1:8080"));
		assertNull(CushtyApiClient.parseServerUrl("http://cushty.example.com"));
		assertNull(CushtyApiClient.parseServerUrl("not a url"));
		assertNull(CushtyApiClient.parseServerUrl(""));
		assertNull(CushtyApiClient.parseServerUrl(null));
	}

	@Test
	public void serialisesPayloadMatchingProtocol()
	{
		EventPayload payload = EventPayload.builder()
			.type(EventPayload.TYPE_LOOT)
			.rsn("Zezima")
			.loot(new EventPayload.Loot("Vorkath", List.of(new EventPayload.LootItem(22006, "Skeletal visage", 1, 30_000_000L)), 30_250_000L))
			.build();

		// A plain Gson here only checks the JSON shape. The plugin injects RuneLite's Gson.
		assertEquals(
			"{\"type\":\"loot\",\"rsn\":\"Zezima\",\"loot\":{\"source\":\"Vorkath\",\"items\":[{\"id\":22006,\"name\":\"Skeletal visage\",\"quantity\":1,\"priceEach\":30000000}],\"totalValue\":30250000}}",
			new Gson().toJson(payload));
	}
}

package com.cushty.capture;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class CaptureFramesTest
{
	@Test
	public void buildsARectangleFromEitherDragDirection()
	{
		Rectangle area = CaptureFrames.fromPoints(new Point(30, 40), new Point(10, 15));
		assertEquals(new Rectangle(10, 15, 20, 25), area);
	}

	@Test
	public void rejectsWidgetsThatCoverTheWholeCanvas()
	{
		assertFalse(CaptureFrames.include(new Rectangle(0, 0, 800, 600), 800, 600));
		assertTrue(CaptureFrames.include(new Rectangle(0, 340, 519, 142), 765, 503));
		assertFalse(CaptureFrames.include(new Rectangle(0, 0, 4, 4), 765, 503));
	}

	@Test
	public void scalesCanvasCoordinatesOntoALargerImage()
	{
		Rectangle scaled = CaptureFrames.scale(new Rectangle(100, 200, 50, 40), 2000, 1600, 1000, 800);
		assertEquals(new Rectangle(200, 400, 100, 80), scaled);
	}

	@Test
	public void clampsACropThatStartsOffTheImage()
	{
		Rectangle scaled = CaptureFrames.scale(new Rectangle(-10, -10, 30, 30), 100, 100, 100, 100);
		assertEquals(new Rectangle(0, 0, 20, 20), scaled);
		BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_RGB);
		BufferedImage crop = CaptureFrames.crop(image, scaled);
		assertEquals(20, crop.getWidth());
		assertEquals(20, crop.getHeight());
	}

	@Test
	public void dropsAnEmptyScaledArea()
	{
		assertNull(CaptureFrames.scale(new Rectangle(200, 200, 10, 10), 100, 100, 100, 100));
	}
}

package com.cushty.capture;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.ChatMessageType;
import org.junit.Test;

public class PrivateChatRedactorTest
{
	@Test
	public void blocksIncomingOutgoingAndModeratorPrivateMessages()
	{
		assertTrue(PrivateChatRedactor.isPrivate(ChatMessageType.PRIVATECHAT));
		assertTrue(PrivateChatRedactor.isPrivate(ChatMessageType.PRIVATECHATOUT));
		assertTrue(PrivateChatRedactor.isPrivate(ChatMessageType.MODPRIVATECHAT));
		assertFalse(PrivateChatRedactor.isPrivate(ChatMessageType.PUBLICCHAT));
		assertFalse(PrivateChatRedactor.isPrivate(ChatMessageType.GAMEMESSAGE));
		assertFalse(PrivateChatRedactor.isPrivate(ChatMessageType.LOGINLOGOUTNOTIFICATION));
		assertFalse(PrivateChatRedactor.isPrivate(ChatMessageType.FRIENDSCHAT));
	}

	@Test
	public void clearsTheShowFlagForAPrivateLine()
	{
		int[] stack = stack(ChatMessageType.PRIVATECHATOUT);
		PrivateChatRedactor.apply(stack, stack.length);
		assertEquals(0, stack[0]);

		int[] game = stack(ChatMessageType.GAMEMESSAGE);
		PrivateChatRedactor.apply(game, game.length);
		assertEquals(1, game[0]);
	}

	@Test
	public void ignoresAShortStack()
	{
		int[] stack = new int[] {1, ChatMessageType.PRIVATECHAT.getType()};
		PrivateChatRedactor.apply(stack, stack.length);
		assertEquals(1, stack[0]);
	}

	private static int[] stack(ChatMessageType type)
	{
		// Show flag, message type, message id. Matches the chatFilterCheck script.
		return new int[] {1, type.getType(), 42};
	}
}

package com.cushty.loot;

import static org.junit.Assert.assertEquals;
import com.cushty.api.EventPayload.LootItem;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

public class LootFilterTest
{
	private static List<String> names(LootFilter.Result result)
	{
		return result.getItems().stream().map(LootItem::getName).collect(Collectors.toList());
	}

	@Test
	public void selectsStacksOverThresholdMostValuableFirst()
	{
		LootFilter filter = new LootFilter(LootFilter.MIN_STACK_VALUE);
		LootFilter.Result result = filter.select(List.of(
			new LootItem(1, "Dragon bones", 2, 2_000),
			new LootItem(2, "Draconic visage", 1, 4_000_000),
			new LootItem(3, "Skeletal visage", 1, 30_000_000),
			new LootItem(4, "Twisted bow", 1, 1_000_000_000),
			new LootItem(5, "Rune dart", 600, 2_000)));

		assertEquals(List.of("Twisted bow", "Skeletal visage"), names(result));
		assertEquals(1_000_000_000L + 30_000_000 + 4_000_000 + 1_200_000 + 4_000, result.getTotalValue());
	}

	@Test
	public void raisesThresholdsBelowTheFloor()
	{
		LootFilter filter = new LootFilter(1);
		LootFilter.Result result = filter.select(List.of(
			new LootItem(1, "Bones", 1, 0),
			new LootItem(2, "Draconic visage", 1, 4_000_000),
			new LootItem(3, "Twisted bow", 1, LootFilter.MIN_STACK_VALUE)));

		assertEquals(List.of("Twisted bow"), names(result));
	}

	@Test
	public void capsItemCount()
	{
		List<LootItem> drop = new ArrayList<>();
		for (int i = 0; i < 40; i++)
		{
			drop.add(new LootItem(i, "Item " + i, 1, LootFilter.MIN_STACK_VALUE + i));
		}
		LootFilter.Result result = new LootFilter(LootFilter.MIN_STACK_VALUE).select(drop);
		assertEquals(LootFilter.MAX_ITEMS, result.getItems().size());
		assertEquals("Item 39", result.getItems().get(0).getName());
	}

	@Test
	public void includesWatchlistItemsUnderThreshold()
	{
		LootFilter filter = new LootFilter(LootFilter.MIN_STACK_VALUE, List.of(526));
		LootFilter.Result result = filter.select(List.of(
			new LootItem(526, "Bones", 1, 0),
			new LootItem(2, "Cheap junk", 1, 100)));

		assertEquals(List.of("Bones"), names(result));
	}
}

